/**
 * K3 — Complete word-editor command router.
 *
 * Bridges the 78 ribbon spec commands (word-ribbon.ts) to actual effects in
 * the WASM canvas editor. Replaces the 9-command format-only router that
 * previously lived inline in DocumentHolder.tsx.
 *
 * Wiring paths (see plan/ribbon-command-wiring.md):
 *   wasm   → applyFormatting (bold, italic, align, heading, …)
 *   store  → DocumentStore toggles / actions
 *   panel  → open right-side panel
 *   lib    → existing lib functions (track-changes, footnotes, toc, …)
 *   ui     → document events handled by App.tsx (find/replace etc.)
 */

import { type WoCommand, togglePluginEnabled } from "@world-office/editor-common"
import type { CanvasEditorHandle, WoPasteOption } from "../components/CanvasEditor"
import { documentStore } from "../stores/DocumentStore"
import type { RichTextCommand } from "./rte-command"
import { getWasmApi } from "./wasm-renderer"

export type WordCommandHandler = (cmd: WoCommand) => void

export interface WordCommandDeps {
  /** WASM editor handle (applyFormatting + focus) */
  editorRef: React.RefObject<CanvasEditorHandle | null>
  /** Dispatch a rich-text command (used for Monaco/text mode fallbacks) */
  onRichTextCommand: (cmd: RichTextCommand, value?: string) => void
  /** Open the find/replace UI (App.tsx wires this) */
  onFind?: (replace: boolean) => void
}

/**
 * Map a ribbon command to a WASM structure op (list, table, break, rule).
 * Returns null when the command is not a structure op.
 */
export function structureOpForCommand(command: string): string | null {
  switch (command) {
    case "bulletList":
    case "bullet-list":
      return "bullet-list"
    case "orderedList":
    case "ordered-list":
      return "ordered-list"
    case "taskList":
    case "task-list":
      return "task-list"
    case "indent":
      return "indent"
    case "outdent":
      return "outdent"
    case "insertSectionBreak":
    case "insert-section-break":
      return "insert-section-break"
    case "insertContinuousSectionBreak":
    case "insert-continuous-section-break":
      return "insert-continuous-section-break"
    case "horizontalRule":
    case "horizontal-rule":
      return "horizontal-rule"
    case "pageBreak":
    case "page-break":
      return "page-break"
    // OO "Blank Page" inserts a page break at the cursor, pushing the
    // following content onto a fresh page (same real WASM model op).
    case "blankPage":
    case "blank-page":
      return "page-break"
    case "blockquote":
      return "blockquote"
    case "codeBlock":
      return "code-block"
    default:
      return null
  }
}

/**
 * Standard OnlyOffice font-size ladder (points). Ribbon Inc./Dec. font size
 * buttons step along it; a non-ladder start value is snapped to the nearest
 * rung before stepping.
 */
const FONT_SIZE_LADDER = [8, 9, 10, 11, 12, 14, 16, 18, 20, 24, 28, 36, 48, 72]

/** Next / previous ladder size in points; defaults to stepping from 12pt. */
export function stepFontSize(value: string | undefined, dir: 1 | -1): number {
  const current = value ? Number.parseFloat(value) : 12
  const idx = FONT_SIZE_LADDER.indexOf(current)
  if (idx === -1) return FONT_SIZE_LADDER[0]
  return FONT_SIZE_LADDER[Math.min(FONT_SIZE_LADDER.length - 1, Math.max(0, idx + dir))]
}

/**
 * Map a ribbon command + value to a WASM applyFormatting JSON object.
 * Returns null when the command is not a formatting op.
 */
export function commandToFormat(command: string, value?: string): Record<string, unknown> | null {
  switch (command) {
    case "bold":
      return { bold: true }
    case "italic":
      return { italic: true }
    case "underline":
      return { underline: value ?? "single" }
    case "strike":
    case "strikethrough":
      return { strikethrough: true }
    case "subscript":
      return { verticalAlignment: "subscript" }
    case "superscript":
      return { verticalAlignment: "superscript" }
    case "fontSize":
      return { fontSize: value ? Number.parseInt(value, 10) * 2 : 24 }
    case "increaseFontSize":
      // Half-points (1pt = 2 half-points), matching the font-size select.
      return { fontSize: stepFontSize(value, 1) * 2 }
    case "decreaseFontSize":
      return { fontSize: stepFontSize(value, -1) * 2 }
    case "fontFamily":
      return value ? { fontName: value } : null
    case "textColor":
      return value ? { textColor: value } : null
    case "highlight":
    case "highlightColor":
      return value ? { highlight: value } : null
    case "clearFormatting":
      return { clearFormatting: true }
    case "alignLeft":
      return { align: "left" }
    case "alignCenter":
      return { align: "center" }
    case "alignRight":
      return { align: "right" }
    case "alignJustify":
      return { align: "justify" }
    case "heading1":
      return { heading: 1 }
    case "heading2":
      return { heading: 2 }
    case "heading3":
      return { heading: 3 }
    case "heading4":
      return { heading: 4 }
    case "heading5":
      return { heading: 5 }
    case "heading6":
      return { heading: 6 }
    case "lineSpacing": {
      // value is a line-spacing factor like "1", "1.15", "1.5", "2"
      // → OOXML spacing_line in 240ths (1.15 = 276, 1.5 = 360, 2 = 480).
      const factor = value ? Number.parseFloat(value) : 1.15
      return { lineSpacing: Math.round(factor * 240) }
    }
    default:
      return null
  }
}

/**
 * Extract the run formatting of the current selection as the raw WASM JSON
 * string — the capture behind `copyStyle` (Ctrl+Alt+C) and
 * "Formatting as style". Returns null when no WASM document is mounted.
 */
function extractSelectionFormatting(
  editorRef: React.RefObject<CanvasEditorHandle | null>,
): string | null {
  const docHandle = editorRef.current?.getDocHandle?.() ?? null
  const api = docHandle !== null ? getWasmApi() : null
  if (api === null || docHandle === null) return null
  try {
    return api.get_run_formatting(docHandle)
  } catch {
    // WASM not ready — behave like "nothing captured"
    return null
  }
}

/**
 * PGP-6 — Style Title: user-named styles ("formatting as style").
 *
 * OO's context-menu row "Formatting as style" opens the Style Title dialog:
 * the current selection's formatting is captured and saved under a
 * user-chosen name, and named styles can be renamed in place. This is the
 * react equivalent — a module-level registry of { name, formatting } pairs
 * holding the same run-formatting snapshot `copyStyle` captures, rendered by
 * StylesPanel (the "paragraph" right rail) with inline naming / renaming
 * (no window.prompt).
 *
 * ponytail: the registry is in-memory and survives only the session;
 * persisting user styles with the document is a follow-up.
 */
export interface UserStyle {
  id: string
  name: string
  /** WASM applyFormatting snapshot (get_run_formatting) captured at save time. */
  formatting: Record<string, unknown>
  createdAt: number
}

const userStyles: UserStyle[] = []
let userStyleSeq = 0
const userStyleListeners = new Set<() => void>()

function emitUserStylesChange(): void {
  for (const listener of userStyleListeners) listener()
}

/** Trim + collapse inner whitespace; whitespace-only names are rejected. */
export function normalizeStyleName(name: string | undefined): string | null {
  if (typeof name !== "string") return null
  const normalized = name.trim().replace(/\s+/g, " ")
  return normalized.length > 0 ? normalized : null
}

/** Next free OO-style default name ("Style 1", "Style 2", …). */
function nextDefaultStyleName(): string {
  const taken = new Set(userStyles.map((style) => style.name.toLowerCase()))
  let n = userStyles.length + 1
  while (taken.has(`style ${n}`)) n += 1
  return `Style ${n}`
}

/** Current user-named styles (oldest first). */
export function getUserStyles(): readonly UserStyle[] {
  return userStyles
}

/**
 * Register a captured formatting snapshot under a name. A blank name gets
 * the next free default ("Style N"); re-saving an existing name redefines
 * that style in place (OO style-update semantics).
 */
export function saveUserStyle(
  name: string | undefined,
  formatting: Record<string, unknown>,
): UserStyle {
  const normalized = normalizeStyleName(name)
  if (normalized !== null) {
    const existing = userStyles.find(
      (style) => style.name.toLowerCase() === normalized.toLowerCase(),
    )
    if (existing) {
      existing.formatting = formatting
      existing.createdAt = Date.now()
      emitUserStylesChange()
      return existing
    }
  }
  userStyleSeq += 1
  const entry: UserStyle = {
    id: `user-style-${userStyleSeq}`,
    name: normalized ?? nextDefaultStyleName(),
    formatting,
    createdAt: Date.now(),
  }
  userStyles.push(entry)
  emitUserStylesChange()
  return entry
}

/** Rename a saved style (the OO Style Title rename flow). */
export function renameUserStyle(id: string, name: string): boolean {
  const normalized = normalizeStyleName(name)
  if (normalized === null) return false
  const entry = userStyles.find((style) => style.id === id)
  if (!entry) return false
  if (entry.name === normalized) return true
  entry.name = normalized
  emitUserStylesChange()
  return true
}

/** Look up a saved style by id, exact name, then case-insensitive name. */
export function findUserStyle(idOrName: string): UserStyle | null {
  return (
    userStyles.find((style) => style.id === idOrName) ??
    userStyles.find((style) => style.name === idOrName) ??
    userStyles.find((style) => style.name.toLowerCase() === idOrName.toLowerCase()) ??
    null
  )
}

/** Re-render hook for surfaces listing the registry (StylesPanel). */
export function subscribeUserStyles(listener: () => void): () => void {
  userStyleListeners.add(listener)
  return () => {
    userStyleListeners.delete(listener)
  }
}

/** Drop every user style (session reset). */
export function resetUserStyles(): void {
  userStyles.length = 0
  emitUserStylesChange()
}

/**
 * Latest editor ref registered by createWordCommandHandler — lets the
 * registry helpers below reach the WASM engine from panel code.
 */
let activeEditorRef: React.RefObject<CanvasEditorHandle | null> | null = null

/**
 * Capture the current selection's run formatting as a parsed snapshot
 * (registry input). Returns null when no WASM document is mounted.
 */
export function captureSelectionFormatting(): Record<string, unknown> | null {
  if (activeEditorRef === null) return null
  const raw = extractSelectionFormatting(activeEditorRef)
  if (raw === null) return null
  try {
    return raw ? (JSON.parse(raw) as Record<string, unknown>) : {}
  } catch {
    return null
  }
}

/**
 * Apply a saved style to the current selection — the FormattingAsStyle
 * apply path: the stored snapshot replays through the copyStyle apply
 * path (WASM applyFormatting).
 */
export function applyUserStyle(idOrName: string): boolean {
  const entry = findUserStyle(idOrName)
  if (entry === null || activeEditorRef === null) return false
  activeEditorRef.current?.applyFormatting(entry.formatting)
  return true
}

/**
 * Create the full word-command handler.
 */
export function createWordCommandHandler(deps: WordCommandDeps): WordCommandHandler {
  const { editorRef, onRichTextCommand, onFind } = deps
  // Registry helpers (captureSelectionFormatting / applyUserStyle) reuse
  // the handler's editor ref so StylesPanel can drive the same paths.
  activeEditorRef = editorRef

  return (cmd: WoCommand): void => {
    const command = cmd.command
    const value = typeof cmd.value === "string" ? cmd.value : undefined

    // 1. Toggle formatting commands (bold, italic, underline, strikethrough)
    //    Read current state from WASM and flip it
    if (
      command === "bold" ||
      command === "italic" ||
      command === "underline" ||
      command === "strike" ||
      command === "strikethrough"
    ) {
      const editorHandle = editorRef.current
      if (editorHandle) {
        const docHandle = editorHandle.getDocHandle?.() ?? null
        const api = docHandle !== null ? getWasmApi() : null
        if (api !== null && docHandle !== null) {
          try {
            const currentFormatting = api.get_run_formatting(docHandle)
            const current = currentFormatting ? JSON.parse(currentFormatting) : {}

            // Determine the formatting key and toggle value
            let format: Record<string, unknown>
            switch (command) {
              case "bold":
                format = { bold: !current.bold }
                break
              case "italic":
                format = { italic: !current.italic }
                break
              case "underline":
                // If underline is currently set, remove it (null); otherwise set to value or "single"
                format = { underline: current.underline ? null : (value ?? "single") }
                break
              case "strike":
              case "strikethrough":
                format = { strikethrough: !current.strikethrough }
                break
              default:
                // Fall through to regular formatting
                format = commandToFormat(command, value) ?? {}
            }
            editorHandle.applyFormatting(format)
          } catch {
            // If reading formatting fails, fall back to setting it to true
            const format = commandToFormat(command, value)
            if (format) {
              editorHandle.applyFormatting(format)
            }
          }
        } else {
          // No WASM handle available, fall back to setting it to true
          const format = commandToFormat(command, value)
          if (format) {
            editorRef.current?.applyFormatting(format)
          }
        }
        return
      }
    }

    // 2. Formatting commands → WASM applyFormatting
    const format = commandToFormat(command, value)
    if (format) {
      editorRef.current?.applyFormatting(format)
      return
    }

    // 2. Structure ops → WASM apply_structure_op (lists, tables, breaks)
    //    setTextDirection has a value param (ltr/rtl), handle separately
    if (command === "setTextDirection") {
      editorRef.current?.applyStructureOp(
        value === "rtl" ? "set-text-direction-rtl" : "set-text-direction-ltr",
      )
      return
    }
    if (command === "multilevelList") {
      // OO "Multilevel list" = a decimal-numbered list with nested levels.
      // The WASM engine has no single multilevel op, so run the two real
      // ops that reproduce it: start a decimal list, then deepen its level
      // (ilvl + 1) so the item renders as a nested multi-level item.
      editorRef.current?.applyStructureOp("ordered-list")
      editorRef.current?.applyStructureOp("indent")
      return
    }
    // List Settings / List Types pickers — numbering format (decimal /
    // alpha / roman) and per-level indent. The WASM engine has no op for
    // these, so route them to the TipTap rich-text bridge which owns the
    // orderedList `type` attr and sink/liftListItem nesting.
    if (command === "listNumberingStyle" || command === "listIndent") {
      onRichTextCommand(command as RichTextCommand, value)
      return
    }
    // OO table ctx-menu "Distribute Rows / Columns" — the WASM engine has no
    // distribute op, the TipTap bridge owns the equal-width/height model
    // change (rte-command.ts distributeTable{Rows,Columns}).
    if (command === "distributeRows" || command === "distributeColumns") {
      onRichTextCommand(command as RichTextCommand, value)
      return
    }
    // OO text ctx-menu "Page break before" / "Keep lines together" — the
    // WASM engine has no pagination op, the TipTap bridge owns the paragraph
    // pagination attributes (rte-command.ts setParagraphPagination).
    if (command === "pageBreakBefore" || command === "keepLines") {
      onRichTextCommand(command as RichTextCommand, value)
      return
    }
    // OO image/shape ctx-menu rows that change the node model (PGP-A2/A3) —
    // the WASM engine has no image/shape op, the TipTap bridge owns
    // rotation / actual size / replace / save-as-image and the figure
    // caption insert (rte-command.ts).
    if (
      command === "rotateImage" ||
      command === "actualSize" ||
      command === "replaceImage" ||
      command === "saveAsImage" ||
      command === "rotateShape" ||
      command === "insertCaptionFigure"
    ) {
      onRichTextCommand(command as RichTextCommand, value)
      return
    }
    // OO References ▸ "Notes Remove" — delete every footnote / endnote
    // (reference marks + note content). The WASM engine has no note model,
    // the TipTap bridge owns the removal (rte-command.ts).
    if (
      command === "removeAllFootnotes" ||
      command === "removeAllEndnotes" ||
      command === "removeAllNotes"
    ) {
      onRichTextCommand(command as RichTextCommand, value)
      return
    }
    if (command === "drawSelect") {
      editorRef.current?.applyStructureOp("select-tool")
      return
    }
    if (command === "drawEraser") {
      editorRef.current?.applyStructureOp("eraser-tool")
      return
    }
    const structureOp = structureOpForCommand(command)
    if (structureOp) {
      editorRef.current?.applyStructureOp(structureOp)
      return
    }

    // 3. Clipboard commands → native browser APIs for canvas mode,
    //    or TipTap bridge for rich-text mode
    if (command === "copy" || command === "cut" || command === "paste") {
      // Canvas mode: drive the WASM engine (the DOM selection is empty on the
      // canvas editor; applyFormatting({insertText}) was a no-op that only
      // looked like a mutation).
      const handle = editorRef.current
      const docHandle = handle?.getDocHandle?.() ?? null
      if (handle && docHandle !== null) {
        if (command === "copy") {
          handle.clipboardCopy()
          return
        }
        if (command === "cut") {
          handle.clipboardCut()
          return
        }
        if (command === "paste") {
          // Default paste = OO SpecialOptionsKeepSourceFormat (source
          // structure kept). The option list itself is `pasteOptions`.
          handle.pasteWithOption("keep-source-format")
          return
        }
      }
      // Text-mode fallback
      if (command === "copy") {
        const selectedText = window.getSelection()?.toString()
        if (selectedText) {
          void navigator.clipboard.writeText(selectedText)
          return
        }
      } else if (command === "paste") {
        void navigator.clipboard.readText().then((text) => {
          if (text && editorRef.current) {
            // Insert pasted text via WASM applyFormatting insertText
            editorRef.current.applyFormatting({ insertText: text })
          }
        })
        return
      } else if (command === "cut") {
        const selectedText = window.getSelection()?.toString()
        if (selectedText && editorRef.current) {
          // Copy to clipboard
          void navigator.clipboard.writeText(selectedText)
          // Then delete selection via WASM by inserting empty text
          editorRef.current.applyFormatting({ insertText: "" })
          // NOTE: Full cut support requires WASM delete_selection API
          // Current workaround: copy + insert empty text
        }
        return
      }
    }

    // 3b. OO paste-special option set + open-document tab cycling.
    //     The chords live in CanvasEditor (the key surface); both route
    //     through here so a ribbon/control trigger shares the same path.
    if (command === "pasteOptions") {
      editorRef.current?.openPasteOptions()
      return
    }
    if (command === "pasteSpecial") {
      const option = value as WoPasteOption | undefined
      if (option) editorRef.current?.pasteWithOption(option)
      else editorRef.current?.openPasteOptions()
      return
    }
    if (command === "nextFileTab" || command === "previousFileTab") {
      const activated = editorRef.current?.cycleFileTab(command === "nextFileTab" ? 1 : -1)
      if (!activated) {
        documentStore.setStatusMessage("No open document to switch to", 10000)
      }
      return
    }

    // 4. Edit history → TipTap bridge (for Monaco editor)
    if (command === "undo" || command === "redo" || command === "selectAll") {
      // Canvas mode: drive the WASM engine directly (TipTap fallback is a
      // no-op here — the ribbon undo button was dead on the canvas editor).
      const handle = editorRef.current
      if (handle) {
        if (command === "undo") handle.undo()
        else if (command === "redo") handle.redo()
        else handle.selectAll()
        return
      }
      onRichTextCommand(command as RichTextCommand, value)
      return
    }

    // 3. Store toggles (view tab + layout)
    switch (command) {
      case "toggleRuler":
        documentStore.toggleRuler()
        return
      case "toggleGridlines":
        documentStore.toggleGridlines()
        return
      case "toggleNavigation":
        documentStore.toggleNavigation()
        return
      case "toggleSpellCheck":
        documentStore.setSpellingEnabled(!documentStore.spellingEnabled)
        return
      case "zoomIn":
        documentStore.zoomIn()
        return
      case "zoomOut":
        documentStore.zoomOut()
        return
      case "fitToPage":
        documentStore.setFitToPage(true)
        return
      case "fitToWidth":
        documentStore.setFitToWidth(true)
        return
      case "multiplePages":
        documentStore.toggleMultiplePages()
        return
      case "differentFirstPage":
        documentStore.setDifferentFirstPage(!documentStore.differentFirstPage)
        return
      case "differentOddEven":
        documentStore.setDifferentOddEven(!documentStore.differentOddEven)
        return
      case "removeHeader":
        documentStore.clearHeader()
        documentStore.headerFooterMode = "none"
        return
      case "removeFooter":
        documentStore.clearFooter()
        documentStore.headerFooterMode = "none"
        return
      case "editHeader":
      case "insertHeaderFooter":
        documentStore.headerFooterMode = "header"
        return
      case "editFooter":
        documentStore.headerFooterMode = "footer"
        return
      case "insertPageNumber":
        documentStore.headerFooterMode = "footer"
        return
      case "insertDateTime": {
        // OO inserts an updatable DATETIME field into the active region
        const stamp = new Date().toISOString()
        if (documentStore.headerFooterMode === "footer") {
          documentStore.footerHtml += `<span data-wo-field="DATETIME">${stamp}</span>`
        } else {
          documentStore.headerFooterMode = "header"
          documentStore.headerHtml += `<span data-wo-field="DATETIME">${stamp}</span>`
        }
        return
      }
      case "insertField": {
        // OO field dialog inserts a named field (PAGE, NUMPAGES, …);
        // default to PAGE when opened without a selection.
        // Only divert into the header/footer html when that region is ACTIVE —
        // at rest the field belongs in the body (editor-contract.spec.tsx).
        const name = typeof value === "string" && value ? value : "PAGE"
        if (documentStore.headerFooterMode === "footer") {
          documentStore.footerHtml += `<span data-wo-field="${name}">${name}</span>`
        } else if (documentStore.headerFooterMode === "header") {
          documentStore.headerHtml += `<span data-wo-field="${name}">${name}</span>`
        } else {
          // no region active → the field belongs in the body (rte-command path)
          onRichTextCommand("insertField" as RichTextCommand, value)
        }
        return
      }
      case "closeHeaderFooter":
        documentStore.headerFooterMode = "none"
        return
      case "lineNumbers":
        documentStore.setLineNumbersEnabled(!documentStore.lineNumbersEnabled)
        return
      case "bringForward":
        documentStore.bringForward()
        return
      case "sendBackward":
        documentStore.sendBackward()
        return
      case "alignObjects":
        documentStore.alignObjects()
        return
      case "groupObjects":
        documentStore.groupObjects()
        return
      case "mergeShapes":
        documentStore.mergeShapes()
        return
      // View tab
      case "zoomTo100":
        documentStore.setZoomLevel(100)
        return
      case "interfaceTheme":
        if (value) documentStore.setTheme(value)
        return
      case "toggleDarkDocument":
        if (value !== undefined) {
          documentStore.setDarkDocument(value !== "false")
        } else {
          documentStore.toggleDarkDocument()
        }
        return
      case "macros":
        documentStore.toggleRightPanel("plugins")
        return
      case "recordMacro":
        documentStore.toggleMacroRecording()
        return
      case "pauseMacroRecording":
        documentStore.toggleMacroPause()
        return
      case "save":
        void documentStore.saveToWopi()
        return
      case "download":
        documentStore.exportAsDownload()
        return
      case "wordCount":
        documentStore.toggleRightPanel("word-count")
        return
      case "setDocumentLanguage":
        // Real document-language path (GL2-1): apply the language, then
        // disclose the document-language picker — the OO "Language" dialog the
        // statusbar renders (select#doc-lang, opened through the
        // world-office:doc-language event). The ctx-menu "Select language" row
        // and the ribbon Language button both dispatch this command, so every
        // surface opens the same picker instead of the plugins panel.
        documentStore.setLanguage(value || "en-US")
        window.dispatchEvent(
          new CustomEvent("world-office:doc-language", { detail: { open: true } }),
        )
        return
      case "toggleMultiplePages":
        documentStore.toggleMultiplePages()
        return
      default:
        break
    }

    // 3b. OnlyOffice File backstage — open the matching FileMenu panel (or
    //     return to the document). The panel ids mirror FileMenuItems actions.
    switch (command) {
      case "back":
        documentStore.setFileMenuOpen(false)
        documentStore.setActiveFileMenuPanel(null)
        return
      case "downloadAs":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("saveas")
        return
      case "print":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("printpreview")
        return
      case "protect":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("protect")
        return
      case "info":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("info")
        return
      case "advancedSettings":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("opts")
        return
      case "help":
      case "suggestFeature":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("help")
        return
      default:
        break
    }

    // 4. Page-layout commands — dispatch CustomEvents directly
    //    (works without TipTap; Viewport.tsx listens for these)
    switch (command) {
      case "pageOrientation": {
        const orientation = value || documentStore.pageOrientation || "portrait"
        window.dispatchEvent(
          new CustomEvent("world-office:page-layout", {
            detail: {
              orientation,
              pageSize: documentStore.pageSize || "A4",
              margins: documentStore.pageMargins || "normal",
            },
          }),
        )
        return
      }
      case "pageSize": {
        const size = value || documentStore.pageSize || "A4"
        window.dispatchEvent(
          new CustomEvent("world-office:page-layout", {
            detail: {
              orientation: documentStore.pageOrientation || "portrait",
              pageSize: size,
              margins: documentStore.pageMargins || "normal",
            },
          }),
        )
        return
      }
      case "pageMargins": {
        const margins = value || documentStore.pageMargins || "normal"
        window.dispatchEvent(
          new CustomEvent("world-office:page-layout", {
            detail: {
              orientation: documentStore.pageOrientation || "portrait",
              pageSize: documentStore.pageSize || "A4",
              margins,
            },
          }),
        )
        return
      }
      case "columns": {
        const n = value ? Number.parseInt(value, 10) : 2
        window.dispatchEvent(
          new CustomEvent("world-office:columns", {
            detail: { count: Math.min(Math.max(n, 1), 3) },
          }),
        )
        return
      }
      default:
        break
    }

    // 4.5. Insert text from a file — OO "Text from File" opens a picker and
    //      inserts the chosen file's contents at the cursor. Real behavior:
    //      hidden file input → read as text → WASM insertText model op.
    if (command === "textFromFile") {
      const input = document.createElement("input")
      input.type = "file"
      input.accept = ".txt,.md,.csv,.html,.rtf,.doc,.docx"
      input.style.display = "none"
      input.onchange = () => {
        const file = input.files?.[0]
        if (!file) return
        const reader = new FileReader()
        reader.onload = () => {
          const text = typeof reader.result === "string" ? reader.result : ""
          if (text && editorRef.current) {
            editorRef.current.applyFormatting({ insertText: text })
          }
        }
        reader.readAsText(file)
      }
      document.body.appendChild(input)
      input.click()
      input.remove()
      return
    }

    // 5. Panel-opening commands
    switch (command) {
      case "protectDocument":
      case "protect-document":
      case "encrypt":
        documentStore.setFileMenuOpen(true)
        documentStore.setActiveFileMenuPanel("protect")
        return
      case "find":
        onFind?.(false)
        return
      case "replace":
        onFind?.(true)
        return
      case "addComment":
      case "toggleComment":
      case "deleteComment":
      case "resolveComment":
      case "insertComment":
        documentStore.toggleRightPanel("comments")
        return
      case "image":
        documentStore.toggleRightPanel("image")
        return
      case "shape":
        // "Shape Settings" (OO shape ctx row) → the Shape settings rail
        // (the graphic-object surface insertShape lands on too).
        documentStore.toggleRightPanel("shape")
        return
      case "editPoints":
        // OO "Edit Points" opens the shape vertex editor; this build has
        // no vertex UI yet, so the row opens the Shape settings rail — the
        // divergence is noted in ShapeContextMenu.tsx (still a real panel).
        documentStore.toggleRightPanel("shape")
        return
      case "link":
        documentStore.toggleRightPanel("crossreference")
        return
      case "insertTable":
        documentStore.toggleRightPanel("table")
        return
      // OO table ctx-menu rows that open a settings surface.
      case "tableProperties":
        // "Table Properties" (OO ctx row) → the Table settings right rail.
        documentStore.toggleRightPanel("table")
        return
      case "paragraphSettings":
        // "Paragraph Settings" (OO ctx row) → StylesPanel (paragraph rail).
        documentStore.toggleRightPanel("paragraph")
        return
      case "printSelection":
        // OO prints the current selection natively; no editor command.
        window.print()
        return
      // Insert-tab media/objects: Shape, SmartArt and Text Box land on the
      // existing shapes panel (the graphic-object surface; the WASM engine
      // has no op for floating frames yet) — ponytail: add a real
      // object-insertion model op when the engine exposes them.
      case "insertShape":
      case "insertSmartArt":
      case "textBox":
        documentStore.toggleRightPanel("shape")
        return
      case "insertChart":
        documentStore.toggleRightPanel("chart")
        return
      case "textArt":
        documentStore.toggleRightPanel("textart")
        return
      case "dropCap":
        // Drop cap is paragraph-level formatting → paragraph settings panel
        documentStore.toggleRightPanel("paragraph")
        return
      case "insertContentControl":
        documentStore.toggleRightPanel("form")
        return
      case "equation":
      case "symbol":
        // ponytail: no dedicated equation/symbol surface yet — land in the
        // plugins panel (it lists the enabled Equation Editor plugin); add a
        // real picker panel when the engine exposes object insertion.
        documentStore.toggleRightPanel("plugins")
        return
      case "openTheme":
        documentStore.toggleRightPanel("theme")
        return
      case "openBreaksPanel":
        documentStore.toggleRightPanel("paragraph")
        return
      case "hyphenation":
      case "wrapping":
      case "textWrap":
        documentStore.toggleRightPanel("paragraph")
        return
      case "watermark":
      case "pageColor":
      case "documentColors":
        documentStore.toggleRightPanel("image")
        return
      case "insertPlainTextControl":
      case "insertCheckboxControl":
      case "insertDropdownControl":
      case "insertDatePickerControl":
        documentStore.toggleRightPanel("form")
        return
      case "chat":
        documentStore.toggleLeftPanel("chat")
        return
      case "plugins":
        documentStore.toggleRightPanel("plugins")
        return
      case "pluginManager":
      case "backgroundPlugins":
      case "photoEditor":
      case "crop":
      case "youtube":
      case "ocr":
      case "translator":
      case "mendeley":
      case "thesaurus":
      case "highlightCode":
      case "zotero":
      case "speech":
      case "speechInput":
        // Open the plugins panel (all plugin buttons open the same panel)
        documentStore.toggleRightPanel("plugins")
        return
      case "wordCount":
        // Word count - show word count dialog or open a panel
        // For now, open the plugins panel as a placeholder
        documentStore.toggleRightPanel("plugins")
        return
      case "aiAssistant":
      case "ai-assistant":
      case "aiChatbot":
      case "aiSummarization":
      case "aiTranslation":
      case "aiGrammarSpelling":
      case "aiSettings":
        documentStore.toggleRightPanel("ai-assistant")
        return
      // Chart Design (contextual) commands — real chart panel + view-state
      // events consumed by the canvas chart layer.
      case "chartElements":
      case "editChartData":
      case "chartAdvancedSettings":
      case "chart3DRotation":
        documentStore.toggleRightPanel("chart")
        return
      case "chartElementAxisTitles":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-element", { detail: { element: "axis-titles" } }),
        )
        return
      case "chartElementLegend":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-element", { detail: { element: "legend" } }),
        )
        return
      case "chartElementDataLabels":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-element", { detail: { element: "data-labels" } }),
        )
        return
      case "chartElementGridlines":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-element", { detail: { element: "gridlines" } }),
        )
        return
      case "chartElementErrorBars":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-element", { detail: { element: "error-bars" } }),
        )
        return
      case "chartType":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-type", {
            detail: { type: typeof value === "string" && value ? value : "bar" },
          }),
        )
        return
      case "chartWrapping":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-wrapping", {
            detail: { mode: typeof value === "string" && value ? value : "inline" },
          }),
        )
        return
      case "chartWidth":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-width", {
            detail: { width: value ? Number.parseFloat(value) : 400 },
          }),
        )
        return
      case "chartHeight":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-height", {
            detail: { height: value ? Number.parseFloat(value) : 300 },
          }),
        )
        return
      case "updateChartData":
        window.dispatchEvent(
          new CustomEvent("world-office:chart-update", { detail: { at: Date.now() } }),
        )
        return
      // Track Changes commands
      case "toggleTrackChanges":
        documentStore.setTrackChanges(!documentStore.trackChanges)
        return
      case "toggleCoEditingMode":
        documentStore.setCoEditingMode(!documentStore.coEditingMode)
        return
      case "acceptChange":
      case "acceptAllChanges":
      case "rejectChange":
      case "rejectAllChanges":
      case "nextChange":
      case "previousChange":
      case "compareDocuments":
      case "combineDocuments":
      case "displayMode":
        documentStore.toggleRightPanel("review")
        return
      // Mail Merge opens the mailmerge panel
      case "mailMerge":
        documentStore.toggleRightPanel("mailmerge")
        return
      // Reference commands open the crossreference panel
      case "insertFootnote":
      case "insertEndnote":
      case "insertToc":
      case "updateToc":
      case "insertIndex":
      case "updateIndex":
      case "insertIndexEntry":
      case "addTocText":
      case "insertBookmark":
      case "insertCaption":
      case "insertCrossReference":
      case "insertTableOfFigures":
        documentStore.toggleRightPanel("crossreference")
        return
      case "togglePlugin":
        if (typeof value === "string" && value) togglePluginEnabled(value)
        return
      case "copyStyle": {
        // OO "Copy style" (Ctrl+Alt+C): capture the formatting of the run
        // at the current cursor into app state so a surface with a matching
        // apply-path can re-use it (format painter pattern).
        const raw = extractSelectionFormatting(editorRef)
        if (raw !== null) {
          documentStore.formatPainterFormat = raw
        }
        return
      }
      case "formattingAsStyle": {
        // OO ctx-menu "Formatting as style" + dialogs/Style Title: capture
        // the current selection's formatting and register it under `value`
        // (or the next default "Style N"). StylesPanel's inline input does
        // the naming; revealing it here mirrors the Style Title dialog.
        const formatting = captureSelectionFormatting()
        if (formatting !== null) {
          saveUserStyle(value, formatting)
          if (documentStore.activeRightPanel !== "paragraph") {
            documentStore.toggleRightPanel("paragraph")
          }
        }
        return
      }
      case "applyStyle": {
        // Apply a user-named style (id or name) to the current selection.
        if (typeof value === "string" && value) applyUserStyle(value)
        return
      }
      // Home paragraph-formatting / view controls that have no dedicated
      // WASM model op yet land in the existing paragraph settings panel
      // (StylesPanel — the right-rail component rendered for "paragraph").
      // ponytail: full OO parity needs engine ops for case cycling, paragraph
      // shading/borders and non-printing-marks display; upgrade each command
      // when the WASM model exposes them.
      case "changeCase":
      case "shading":
      case "borders":
      case "toggleNonprinting":
        documentStore.toggleRightPanel("paragraph")
        return
      default:
        break
    }

    // 6. Unknown command — log so the coverage audit can flag it
    console.warn(`[word-commands] unhandled command: ${command}`)
  }
}
